 \\\".lake-packages/mathlib/Mathlib/CategoryTheory/Preadditive/Basic.lean\\\",\\n    \\\"line\\\": 321,\\n    \\\"score\\\": 23.8185\\n  },\\n  {\\n    \\\"name\\\": \\\"AlgebraicGeometry.Scheme.basicOpen_algHom_ext\\\",\\n    \\\"kind\\\": \\\"theorem\\\",\\n    \\\"signature\\\": \\\"theorem basicOpen_algHom_ext [IsAffine X] (g : \\\\u0393(X, \\\\u22a4)) {C : Type u} [CommRing C] [Algebra \\\\u0393(X, \\\\u22a4) C] (\\\\u03c6 \\\\u03c8 : \\\\u0393(X, X.basicOpen g) \\\\u2192\\\\u2090[\\\\u0393(X, \\\\u22a4)] C) : \\\\u03c6 = \\\\u03c8\\\",\\n    \\\"doc\\\": \\\"Any two algebra maps over the global sections out of the sections on a basic open of an affine scheme are equal: the source is a localization of `\\\\u0393(X, \\\\u22a4)`.\\\",\\n    \\\"library\\\": \\\"Algebraic-Jacobian-Challenge-Rebuild\\\",\\n    \\\"file\\\": \\\"MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/SectionsAlgebra.lean\\\",\\n    \\\"line\\\": 66,\\n    \\\"score\\\": 23.7031\\n  },\\n  {\\n    \\\"name\\\": \\\"AlgebraicGeometry.Scheme.Modules.gamma_pushforward_top\\\",\\n    \\\"kind\\\": \\\"lemma\\\",\\n    \\\"signature\\\": \\\"lemma gamma_pushforward_top {X Y : Scheme.{0}} (f : X \\\\u27f6 Y) (M : X.Modules) : \\\\u0393((Scheme.Modules.pushforward f).obj M, \\\\u22a4) = \\\\u0393(M, \\\\u22a4)\\\",\\n    \\\"doc\\\": \\\"Global sections of a pushforward at the maximal open are the global sections of the original sheaf of modules, definitionally.\\\",\\n    \\\"library\\\": \\\"Algebraic-Jacobian-Challenge\\\",\\n    \\\"file\\\": \\\"MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/Picard/SerreTwistSections.lean\\\",\\n    \\\"line\\\": 86,\\n    \\\"score\\\": 23.6489\\n  },\\n  {\\n    \\\"name\\\": \\\"AlgebraicGeometry.Proj.fromOfGlobalSections_resLE\\\",\\n    \\\"kind\\\": \\\"lemma\\\",\\n    \\\"signature\\\": \\\"lemma fromOfGlobalSections_resLE {r : A} {n : \\\\u2115} (hn : 0 < n) (hr : r \\\\u2208 \\\\ud835\\\\udc9c n) : (fromOfGlobalSections \\\\ud835\\\\udc9c f hf).resLE _ _ (fromOfGlobalSections_preimage_basicOpen _ _ _ hn hr).ge = toBasicOpenOfGlobalSections \\\\ud835\\\\udc9c f rfl hn hr\\\",\\n    \\\"doc\\\": \\\"\\\",\\n    \\\"library\\\": \\\"mathlib\\\",\\n    \\\"file\\\": \\\".lake-packages/mathlib/Mathlib/AlgebraicGeometry/ProjectiveSpectrum/Basic.lean\\\",\\n    \\\"line\\\": 500,\\n    \\\"score\\\": 23.6058\\n  },\\n  {\\n    \\\"name\\\": \\\"TruncExpCech.sub_mem_cechCoboundaryAdd\\\",\\n    \\\"kind\\\": \\\"theorem\\\",\\n    \\\"signature\\\": \\\"theorem sub_mem_cechCoboundaryAdd (\\\\u03c1\\\\u2081 : A\\\\u2081 \\\\u2192+* B) (\\\\u03c1\\\\u2082 : A\\\\u2082 \\\\u2192+* B) (a\\\\u2081 : A\\\\u2081) (a\\\\u2082 : A\\\\u2082) : \\\\u03c1\\\\u2081 a\\\\u2081 - \\\\u03c1\\\\u2082 a\\\\u2082 \\\\u2208 cechCoboundaryAdd \\\\u03c1\\\\u2081 \\\\u03c1\\\\u2082\\\",\\n    \\\"doc\\\": \\\"Differences of chart sections are additive \\\\u010cech coboundaries \\\\u2014 the subtraction form of membership, matching the difference-of-restrictions map `AlgebraicGeometry.TwoCover.diff` of the geometric consumer. Clean-binder helper: state and use this on abstract rings, then transport the result along the (defeq) carrier identifications of the sheaf dialect.\\\",\\n    \\\"library\\\": \\\"Algebraic-Jacobian-Challenge-Rebuild\\\",\\n    \\\"file\\\": \\\"MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Tangent/TruncExpCech.lean\\\",\\n    \\\"line\\\": 147,\\n    \\\"score\\\": 23.3741\\n  },\\n  {\\n    \\\"name\\\": \\\"AlgebraicGeometry.Scheme.basicRes\\\",\\n    \\\"kind\\\": \\\"def\\\",\\n    \\\"signature\\\": \\\"def basicRes (g h : \\\\u0393(X, \\\\u22a4)) (hle : X.basicOpen h \\\\u2264 X.basicOpen g) : \\\\u0393(X, X.basicOpen g) \\\\u2192\\\\u2090[\\\\u0393(X, \\\\u22a4)] \\\\u0393(X, X.basicOpen h)\\\",\\n    \\\"doc\\\": \\\"Restriction of sections between nested basic opens, as a map of algebras over the global sections.  (Both algebra structures are the canonical restriction instances.)\\\",\\n    \\\"library\\\": \\\"Algebraic-Jacobian-Challenge-Rebuild\\\",\\n    \\\"file\\\": \\\"MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/SectionsAlgebra.lean\\\",\\n    \\\"line\\\": 43,\\n    \\\"score\\\": 23.3674\\n  },\\n  {\\n    \\\"name\\\": \\\"AlgebraicGeometry.Adelic.linearSystem\\\",\\n    \\\"kind\\\": \\\"def\\\",\\n    \\\"signature\\\": \\\"def linearSystem (D : X.WeilDivisor) : AddSubgroup X.functionField\\\",\\n    \\\"doc\\\": \\\"**The Riemann\\\\u2013Roch space `L(D)`.** Global sections of `\\\\ud835\\\\udcaa_X(D)`: the section over all of `X`. On a 2-affine cover `U\\\\u2080 \\\\u2294 U\\\\u2081 = \\\\u22a4` this is `\\\\u0393(U\\\\u2080, \\\\ud835\\\\udcaa(D)) \\\\u2293 \\\\u0393(U\\\\u2081, \\\\ud835\\\\udcaa(D))`, the kernel of the \\\\u010cech difference map.\\\",\\n    \\\"library\\\": \\\"Algebraic-Jacobian-Challenge\\\",\\n    \\\"file\\\": \\\"MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/RiemannRoch/Adelic/Substrate.lean\\\",\\n    \\\"line\\\": 245,\\n    \\\"score\\\": 23.3632\\n  },\\n  {\\n    \\\"name\\\": \\\"AlgebraicGeometry.Scheme.AffineCoverMVSquare.H0\\\\u2097\\\",\\n    \\\"kind\\\": \\\"def\\\",\\n    \\\"signature\\\": \\\"noncomputable def AffineCoverMVSquare.H0\\\\u2097 (S : C.left.AffineCoverMVSquare) (M : C.left.Modules) : Submodule k (BaseSections C M S.U\\\\u2081 \\\\u00d7 BaseSections C M S.U\\\\u2082)\\\",\\n    \\\"doc\\\": \\\"**`H\\\\u2070` on the cover, as a submodule**: the kernel of the `k`-linear difference map \\\\u2014 pairs of sections agreeing on the overlap.  By the sheaf condition this is the global sections (`globalSectionsEquivH0\\\\u2097`), which is why `h0` is honestly cover-independent already at this wave.\\\",\\n    \\\"library\\\": \\\"Algebraic-Jacobian-Challenge\\\",\\n    \\\"file\\\": \\\"MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/RiemannRoch/CohomologyKit.lean\\\",\\n    \\\"line\\\": 222,\\n    \\\"score\\\": 23.3282\\n  },\\n  {\\n    \\\"name\\\": \\\"CategoryTheory.kernelForkOfFork\\\",\\n    \\\"kind\\\": \\\"def\\\",\\n    \\\"signature\\\": \\\"def kernelForkOfFork (c : Fork f g) : KernelFork (f - g)\\\",\\n    \\\"doc\\\": \\\"Map any equalizer fork to a cone on the difference of the two morphisms.\\\",\\n    \\\"library\\\": \\\"mathlib\\\",\\n    \\\"file\\\": \\\".lake-packages/mathlib/Mathlib/CategoryTheory/Preadditive/Basic.lean\\\",\\n    \\\"line\\\": 329,\\n    \\\"score\\\": 23.1226\\n  },\\n  {\\n    \\\"name\\\": \\\"TwoLatticePair.H0\\\",\\n    \\\"kind\\\": \\\"def\\\",\\n    \\\"signature\\\": \\\"def H0 : Submodule R (M\\\\u2080 \\\\u00d7 M\\\\u2081)\\\",\\n    \\\"doc\\\": \\\"`H\\\\u2070` of the pair: the kernel of the \\\\u010cech differential, as a submodule of `M\\\\u2080 \\\\u00d7 M\\\\u2081`. In the geometric application this computes the global sections of the sheaf.\\\",\\n    \\\"library\\\": \\\"Algebraic-Jacobian-Challenge-Rebuild\\\",\\n    \\\"file\\\": \\\"MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Cohomology/RigidEngineLattice.lean\\\",\\n    \\\"line\\\": 173,\\n    \\\"score\\\": 22.7802\\n  },\\n  {\\n    \\\"name\\\": \\\"AlgebraicGeometry.Scheme.AffineCoverMVSquare.h0_unit_eq_one\\\",\\n    \\\"kind\\\": \\\"theorem\\\",\\n    \\\"signature\\\": \\\"theorem AffineCoverMVSquare.h0_unit_eq_one [IsProper C.hom] [GeometricallyIntegral C.hom] (S : C.left.AffineCoverMVSquare) : S.h0 C (SheafOfModules.unit C.left.ringCatSheaf) = 1\\\",\\n    \\\"doc\\\": \\\"**`h\\\\u2070(\\\\ud835\\\\udcaa_C) = 1`** \\\\u2014 on every 2-affine cover, over every field: the kernel of the difference map is the global sections (`globalSectionsEquivH0\\\\u2097`), which are exactly the constants `k` (`unitTopSectionsEquivBase`).\\\",\\n    \\\"library\\\": \\\"Algebraic-Jacobian-Challenge\\\",\\n    \\\"file\\\": \\\"MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/RiemannRoch/CohomologyKit.lean\\\",\\n    \\\"line\\\": 521,\\n    \\\"score\\\": 22.7441\\n  },\\n  {\\n    \\\"name\\\": \\\"AlgebraicGeometry.Scheme.AffineCoverMVSquare.globalSectionsEquivKerModuleSectionDiffBase\\\",\\n    \\\"kind\\\": \\\"def\\\",\\n    \\\"signature\\\": \\\"noncomputable def AffineCoverMVSquare.globalSectionsEquivKerModuleSectionDiffBase (V : X.AffineCoverMVSquare) (p : X \\\\u27f6 S) (M : X.Modules) : letI\\\",\\n    \\\"doc\\\": \\\"**The kernel identification (work item 1(i)): global sections are the degree-0 \\\\u010cech cohomology of the 2-affine cover.**  The corestriction of the pair-of-restrictions map is a `\\\\u0393(S, \\\\u22a4)`-linear equivalence `\\\\u0393(X, M) \\\\u2243\\\\u2097 ker (moduleSectionDiffBase)`: injective by separatedness of the sheaf `M.presheaf`, surjective onto the kernel by the gluing axiom, both on the 2-element cover `{U\\\\u2081, U\\\\u2082}` of `\\\\u22a4`.  This identifies the `H\\\\u2070` of the two-term complex consumed by the finite replacement with the pushforward sections `\\\\u0393(S, p_* M) = \\\\u0393(X, M)`.\\\",\\n    \\\"library\\\": \\\"Algebraic-Jacobian-Challenge\\\",\\n    \\\"file\\\": \\\"MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/Picard/RigidPushforwardP1Engine.lean\\\",\\n    \\\"line\\\": 287,\\n    \\\"score\\\": 22.7002\\n  },\\n  {\\n    \\\"name\\\": \\\"SheafOfModules.pushforwardSections\\\",\\n    \\\"kind\\\": \\\"def\\\",\\n    \\\"signature\\\": \\\"def pushforwardSections {M : SheafOfModules.{v} R} (s : M.sections) : ((pushforward \\\\u03c6).obj M).sections\\\",\\n    \\\"doc\\\": \\\"The canonical map from the (global) sections of a sheaf of modules to the (global) sections of its pushforward.\\\",\\n    \\\"library\\\": \\\"mathlib\\\",\\n    \\\"file\\\": \\\".lake-packages/mathlib/Mathlib/Algebra/Category/ModuleCat/Sheaf/PullbackFree.lean\\\",\\n    \\\"line\\\": 48,\\n    \\\"score\\\": 22.582\\n  },\\n  {\\n    \\\"name\\\": \\\"CategoryTheory.GrothendieckTopology.MayerVietorisSquare.secti