\\n  {\\n    \\\"name\\\": \\\"DualNumber.sub_mem_cechCoboundaryAdd\\\",\\n    \\\"kind\\\": \\\"theorem\\\",\\n    \\\"signature\\\": \\\"theorem sub_mem_cechCoboundaryAdd (\\\\u03c1\\\\u2081 : A\\\\u2081 \\\\u2192+* B) (\\\\u03c1\\\\u2082 : A\\\\u2082 \\\\u2192+* B) (a\\\\u2081 : A\\\\u2081) (a\\\\u2082 : A\\\\u2082) : \\\\u03c1\\\\u2081 a\\\\u2081 - \\\\u03c1\\\\u2082 a\\\\u2082 \\\\u2208 cechCoboundaryAdd \\\\u03c1\\\\u2081 \\\\u03c1\\\\u2082\\\",\\n    \\\"doc\\\": \\\"Differences of chart sections are additive \\\\u010cech coboundaries \\\\u2014 the subtraction form of membership, matching the difference-of-restrictions map `AffineCoverMVSquare.sectionDiff` of the geometric consumer. Clean-binder helper: state and use this on abstract rings, then transport the result along the (defeq) carrier identifications of the sheaf dialect.\\\",\\n    \\\"library\\\": \\\"Algebraic-Jacobian-Challenge\\\",\\n    \\\"file\\\": \\\"MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/Picard/Pic0DualNumberCocycle.lean\\\",\\n    \\\"line\\\": 803,\\n    \\\"score\\\": 20.3922\\n  },\\n  {\\n    \\\"name\\\": \\\"AlgebraicGeometry.Scheme.Opens.topIso\\\",\\n    \\\"kind\\\": \\\"def\\\",\\n    \\\"signature\\\": \\\"def topIso : \\\\u0393(U, \\\\u22a4) \\\\u2245 \\\\u0393(X, U)\\\",\\n    \\\"doc\\\": \\\"The global sections of the restriction is isomorphic to the sections on the open set.\\\",\\n    \\\"library\\\": \\\"mathlib\\\",\\n    \\\"file\\\": \\\".lake-packages/mathlib/Mathlib/AlgebraicGeometry/Restrict.lean\\\",\\n    \\\"line\\\": 144,\\n    \\\"score\\\": 20.3802\\n  },\\n  {\\n    \\\"name\\\": \\\"AlgebraicGeometry.TwoCover.range_diff_toAddSubgroup\\\",\\n    \\\"kind\\\": \\\"theorem\\\",\\n    \\\"signature\\\": \\\"theorem range_diff_toAddSubgroup : (LinearMap.range (diff k X U\\\\u2080 U\\\\u2081)).toAddSubgroup = cechCoboundaryAdd (X.resHom (inf_le_left : U\\\\u2080 \\\\u2293 U\\\\u2081 \\\\u2264 U\\\\u2080)) (X.resHom (inf_le_right : U\\\\u2080 \\